type Item={id:string;name:string;category:string;qty:number;unit:string;min:number;description?:string;alloc:Record<string,number>;roomMin?:Record<string,number>;sample?:boolean};
type Log={id:string;ts:number;date:string;type:string;item:string;itemId:string;qty:number;loc?:string;note?:string;actor?:string;sample?:boolean};
