 useEffect(()=>{document.documentElement.dataset.theme=theme;document.body.dataset.theme=theme;localStorage.setItem('iip-theme',theme)},[theme]);
 useEffect(()=>{const timer=window.setInterval(()=>setCurrentTime(new Date()),60_000);return()=>window.clearInterval(timer)},[]);
 useEffect(()=>{const syncPage=()=>{const next=pageFromHash();if(authReady&&next==='Access Management'&&!user?.permissions.includes('manageUsers')){window.history.replaceState({page:'Dashboard'},'',window.location.pathname+window.location.search);setPage('Dashboard');return;}setPage(next);setSearch('')};if(window.location.hash)syncPage();window.addEventListener('popstate',syncPage);return()=>window.removeEventListener('popstate',syncPage)},[authReady,user]);
 useEffect(()=>{const onShortcut=(event:KeyboardEvent)=>{if(page==='Inventory'&&(event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();inventorySearchRef.current?.focus()}};window.addEventListener('keydown',onShortcut);return()=>window.removeEventListener('keydown',onShortcut)},[page]);
 useEffect(()=>watchAuth(async signedIn=>{if(signingInRef.current)return;if(!signedIn){setUser(null);setData(null);setAuthReady(true);return}try{const a=await request('/auth/me',{},false);setUser(a.user);try{setData(await request('/state'))}catch(e){setToast(e instanceof Error?e.message:'We couldn’t load the inventory. Refresh and try again.')}}catch(e){setUser(null);setData(null);if(isAuthFailure(e))await signOutUser().catch(()=>{});setToast(e instanceof Error?e.message:'We couldn’t reach the server. Check your connection and refresh.')}finally{setAuthReady(true)}}),[]);
 useEffect(()=>{const h=(e:Event)=>setModal({kind:'out',location:(e as CustomEvent<string>).detail});const expired=(e:Event)=>{setUser(null);setData(null);setToast((e as CustomEvent<string>).detail||'Your session ended for security. Sign in again to continue.');signOutUser().catch(()=>{})};window.addEventListener('iip-issue',h);window.addEventListener('iip-auth-expired',expired);return()=>{window.removeEventListener('iip-issue',h);window.removeEventListener('iip-auth-expired',expired)}},[]);useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),3200);return()=>clearTimeout(t)},[toast]);
 useEffect(()=>{if(page==='Access Management'&&can('manageUsers'))request('/users').then(r=>setUsers(r.users)).catch(e=>setToast(e.message));},[page,user]);
 const signIn=async(email:string,password:string)=>{signingInRef.current=true;try{await signInWithEmail(email,password);let r;try{r=await request('/auth/me',{},false)}catch(e){await signOutUser().catch(()=>{});throw e}setUser(r.user);setData(await request('/state'));setToast(`Signed in as ${r.user.role}.`)}finally{signingInRef.current=false}};
 const signOut=async()=>{try{await signOutUser()}finally{window.history.replaceState({page:'Dashboard'},'',window.location.pathname+window.location.search);setUser(null);setData(null);setPage('Dashboard');setProfileOpen(false)}};
 const createUser=async()=>{setUsersBusy(true);try{await request('/users',{method:'POST',body:JSON.stringify({email:newEmail,username:newUsername,password:newPassword,role:newRole})});setNewEmail('');setNewUsername('');setNewPassword('');setNewRole('viewer');setUsers((await request('/users')).users);setToast('User account created. Share the credentials securely.')}catch(e){setToast(e instanceof Error?e.message:'Could not create user.')}finally{setUsersBusy(false)}};
 const updateUser=async(id:string,patch:Record<string,unknown>)=>{try{await request(`/users/${id}`,{method:'PATCH',body:JSON.stringify(patch)});setUsers((await request('/users')).users);setToast('User account updated.')}catch(e){setToast(e instanceof Error?e.message:'Could not update user.')}};
