 const mutate=async(url:string,method:string,payload?:unknown)=>{setBusy(true);try{const r=await request(url,{method,body:payload?JSON.stringify(payload):undefined});setData(r.state||r);setModal(null);setToast(r.message||'Saved successfully.')}catch(e){setToast(e instanceof Error?e.message:'We couldn’t save your changes. Check your connection and try again.')}finally{setBusy(false)}};
 const items=data?.items||[],logs=data?.log||[],groups=data?.groups||[],locations=data?.locations||[];
 const totalCentral=items.reduce((a,i)=>a+i.qty,0),totalAssigned=items.reduce((a,i)=>a+issued(i),0),low=items.filter(i=>status(i)!=='ok').sort((a,b)=>a.qty/(a.min||1)-b.qty/(b.min||1));
 const recent=useMemo(()=>logs.filter(l=>l.type==='in'||l.type==='out'||l.type==='return').sort((a,b)=>b.ts-a.ts).slice(0,6),[logs]);
 const filtered=useMemo(()=>{let a=items.filter(i=>(!search||i.name.toLowerCase().includes(search.toLowerCase()))&&(cat==='All categories'||i.category===cat)&&(stock==='All stock'||(stock==='Low stock'?status(i)==='low':stock==='Out of stock'?status(i)==='out':status(i)==='ok'))&&(locFilter==='All locations'||(i.alloc[locFilter]||0)>0));return a.sort((x,y)=>sort==='name'?x.name.localeCompare(y.name):sort==='central-low'?x.qty-y.qty:sort==='central-high'?y.qty-x.qty:sort==='assigned'?issued(y)-issued(x):x.category.localeCompare(y.category));},[items,search,cat,stock,locFilter,sort]);
 const go=(value:string)=>{const p=PAGES.find(candidate=>candidate===value);if(!p)return;if(p!==page)window.history.pushState({page:p},'',`${window.location.pathname}${window.location.search}#${pageSlug(p)}`);setPage(p);setSearch('');setNavOpen(false);window.scrollTo({top:0,behavior:'smooth'})};
 const exportExcel=async()=>{try{let r=await fetch(API+'/export',{headers:await authHeaders()});if(r.status===401&&await getIdToken(true).catch(()=>null))r=await fetch(API+'/export',{headers:await authHeaders()});if(!r.ok){const d=await r.json().catch(()=>({} as {error?:string;code?:string}));const err=new ApiError(d.error||'Export failed.',r.status,d.code);if(isAuthFailure(err))window.dispatchEvent(new CustomEvent('iip-auth-expired',{detail:r.status===401?'':err.message}));throw err}const blob=await r.blob(),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=`IIP_Inventory_${dateNow()}.xlsx`;document.body.appendChild(a);a.click();a.remove();window.setTimeout(()=>URL.revokeObjectURL(href),1500);setToast('Excel workbook downloaded.')}catch(e){setToast(e instanceof Error?e.message:'Export failed.')}};
 const reset=async()=>{if(!can('reset')){setToast('Administrator permission required.');return;}setBusy(true);try{const s=await request('/reset',{method:'POST'});setData(s);setModal(null);setToast('Sample inventory restored.')}catch(e){setToast(e instanceof Error?e.message:'We couldn’t restore the sample data. Check your connection and try again.')}finally{setBusy(false)}};
 const hour=currentTime.getHours();
